/* ===== GlobalStone — Corporate Real Estate CSS ===== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #003F2D;
  --secondary: #012A2D;
  --navy: #0A1628;
  --accent-gold: #C5A46D;
  --accent-teal: #1A8A7D;
  --light-gray: #E6E6E6;
  --mid-gray: #8A8F98;
  --off-white: #F5F5F5;
  --white: #FFFFFF;
  --text-dark: #1A1A2E;
  --text-body: #3A3A4A;
  --text-light: #6B6B7B;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'Georgia', 'Times New Roman', serif;
  --max-width: 1280px;
  --section-pad: 80px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font-body); color: var(--text-body); line-height: 1.6; background: var(--white); -webkit-font-smoothing: antialiased; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* --- Typography --- */
h1, h2, h3, h4 { font-family: var(--font-heading); color: var(--text-dark); line-height: 1.2; font-weight: 700; }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.625rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }
p { margin-bottom: 1rem; }
.section-label { font-family: var(--font-body); font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 2px; color: var(--accent-teal); margin-bottom: 12px; }

/* --- Buttons --- */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 0.875rem; font-weight: 600; padding: 14px 28px;
  border-radius: 2px; transition: var(--transition); letter-spacing: 0.5px;
}
.btn-primary { background: var(--primary); color: var(--white); }
.btn-primary:hover { background: var(--secondary); }
.btn-outline { border: 1.5px solid var(--primary); color: var(--primary); background: transparent; }
.btn-outline:hover { background: var(--primary); color: var(--white); }
.btn-gold { background: var(--accent-gold); color: var(--navy); }
.btn-gold:hover { background: #b8944f; }
.btn-white { background: var(--white); color: var(--primary); }
.btn-white:hover { background: var(--light-gray); }
.btn-arrow::after { content: '→'; transition: transform var(--transition); }
.btn-arrow:hover::after { transform: translateX(4px); }

/* --- Header / Navigation --- */
.site-header {
  position: fixed; top: 0; left: 0; width: 100%; z-index: 1000;
  background: var(--white); border-bottom: 1px solid rgba(0,0,0,0.08);
  transition: box-shadow var(--transition);
}
.site-header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; height: 72px;
}
.logo { font-family: var(--font-heading); font-size: 1.5rem; font-weight: 700; color: var(--primary); }
.logo span { color: var(--accent-gold); }

/* Desktop Nav */
.main-nav { display: flex; align-items: center; gap: 0; }
.main-nav > li { position: relative; }
.main-nav > li > a,
.main-nav > li > button {
  display: flex; align-items: center; gap: 4px;
  padding: 24px 16px; font-size: 0.875rem; font-weight: 500;
  color: var(--text-dark); transition: color var(--transition);
}
.main-nav > li > a:hover,
.main-nav > li > button:hover { color: var(--primary); }
.nav-chevron { font-size: 0.625rem; transition: transform var(--transition); }
.nav-item-active .nav-chevron { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  position: absolute; top: 100%; left: 50%; transform: translateX(-50%);
  width: 620px; background: var(--white); border: 1px solid rgba(0,0,0,0.08);
  box-shadow: 0 20px 60px rgba(0,0,0,0.12); border-radius: 0 0 4px 4px;
  opacity: 0; visibility: hidden; pointer-events: none;
  transition: opacity 0.25s ease, visibility 0.25s ease;
  padding: 32px; display: grid; grid-template-columns: 1fr 1fr; gap: 32px;
}
.mega-menu.active { opacity: 1; visibility: visible; pointer-events: auto; }
.mega-menu-col h4 { font-family: var(--font-body); font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--mid-gray); margin-bottom: 16px; }
.mega-menu-col ul li a {
  display: block; padding: 8px 0; font-size: 0.9rem; color: var(--text-dark);
  transition: color var(--transition); border-bottom: 1px solid transparent;
}
.mega-menu-col ul li a:hover { color: var(--primary); }

/* Mobile Nav */
.mobile-toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.mobile-toggle span { display: block; width: 24px; height: 2px; background: var(--text-dark); transition: var(--transition); }
.mobile-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px,5px); }
.mobile-toggle.active span:nth-child(2) { opacity: 0; }
.mobile-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px,-5px); }

.mobile-nav {
  display: none; position: fixed; top: 72px; left: 0; width: 100%; height: calc(100vh - 72px);
  background: var(--white); overflow-y: auto; padding: 24px;
}
.mobile-nav.active { display: block; }
.mobile-nav > li { border-bottom: 1px solid var(--light-gray); }
.mobile-nav > li > a,
.mobile-nav > li > button {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; padding: 16px 0; font-size: 1rem; font-weight: 500; color: var(--text-dark);
}
.mobile-accordion { display: none; padding: 0 0 16px 16px; }
.mobile-accordion.active { display: block; }
.mobile-accordion li { margin-bottom: 4px; }
.mobile-accordion li a { display: block; padding: 8px 0; font-size: 0.9rem; color: var(--text-body); }
.mobile-accordion h5 { font-family: var(--font-body); font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--mid-gray); margin: 8px 0; }

/* --- Hero Sections --- */
.hero {
  position: relative; min-height: 520px; display: flex; align-items: center;
  background-color: var(--navy); overflow: hidden; margin-top: 72px;
}
.hero-bg {
  position: absolute; inset: 0; background-size: cover; background-position: center;
  opacity: 0.35;
}
.hero-overlay { position: absolute; inset: 0; background: linear-gradient(135deg, rgba(10,22,40,0.85) 0%, rgba(0,63,45,0.6) 100%); }
.hero-content { position: relative; z-index: 2; max-width: 640px; padding: 80px 0; }
.hero-content h1 { color: var(--white); margin-bottom: 20px; }
.hero-content p { color: rgba(255,255,255,0.85); font-size: 1.125rem; margin-bottom: 32px; line-height: 1.7; }

.hero-sm { min-height: 360px; }
.hero-sm .hero-content { padding: 60px 0; }

/* --- Featured Insights (3-card row) --- */
.featured-insights { padding: var(--section-pad) 0; background: var(--white); }
.insights-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.insight-card {
  border: 1px solid var(--light-gray); border-radius: 4px; overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
}
.insight-card:hover { box-shadow: 0 8px 30px rgba(0,0,0,0.08); transform: translateY(-4px); }
.insight-card-img {
  height: 200px; background-color: var(--navy); background-size: cover;
  background-position: center; position: relative;
}
.insight-card-img::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(to bottom, transparent 60%, rgba(10,22,40,0.3));
}
.insight-card-body { padding: 24px; }
.insight-card-tag { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--accent-teal); margin-bottom: 10px; }
.insight-card-body h3 { margin-bottom: 8px; font-size: 1.125rem; }
.insight-card-body p { font-size: 0.875rem; color: var(--text-light); margin-bottom: 0; }
.insight-card-date { font-size: 0.8rem; color: var(--mid-gray); margin-top: 12px; }

/* --- Announcement Banner --- */
.announcement-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  padding: 28px 0; text-align: center;
}
.announcement-banner .container { display: flex; align-items: center; justify-content: center; gap: 24px; flex-wrap: wrap; }
.announcement-banner p { color: var(--white); font-size: 1.0625rem; font-weight: 500; margin: 0; }

/* --- About Statement --- */
.about-statement { padding: var(--section-pad) 0; background: var(--off-white); }
.about-inner { max-width: 800px; }
.about-inner h2 { margin-bottom: 24px; }
.about-inner p { font-size: 1.125rem; color: var(--text-body); line-height: 1.8; margin-bottom: 28px; }

/* --- What We Do (Vertical Tabs) --- */
.what-we-do { padding: var(--section-pad) 0; background: var(--white); }
.tabs-wrapper { display: flex; gap: 0; margin-top: 40px; border: 1px solid var(--light-gray); border-radius: 4px; overflow: hidden; min-height: 320px; }
.tabs-nav { display: flex; flex-direction: column; min-width: 240px; background: var(--off-white); border-right: 1px solid var(--light-gray); }
.tab-btn {
  padding: 20px 24px; text-align: left; font-size: 0.9375rem; font-weight: 500;
  color: var(--text-body); border-bottom: 1px solid var(--light-gray);
  transition: var(--transition); position: relative;
}
.tab-btn:last-child { border-bottom: none; }
.tab-btn:hover { background: rgba(0,63,45,0.05); }
.tab-btn.active {
  background: var(--white); color: var(--primary); font-weight: 600;
}
.tab-btn.active::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--primary); }
.tab-panel { display: none; padding: 40px; flex: 1; }
.tab-panel.active { display: flex; flex-direction: column; justify-content: center; }
.tab-panel h3 { margin-bottom: 16px; color: var(--primary); }
.tab-panel p { font-size: 1.0625rem; line-height: 1.8; margin-bottom: 24px; color: var(--text-body); }
.tab-services-list { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 24px; }
.tab-services-list li { font-size: 0.875rem; padding: 6px 14px; background: var(--off-white); border-radius: 20px; color: var(--text-dark); }

/* --- Newsletter --- */
.newsletter { padding: var(--section-pad) 0; background: var(--navy); text-align: center; }
.newsletter h2 { color: var(--white); margin-bottom: 12px; }
.newsletter p { color: rgba(255,255,255,0.7); margin-bottom: 32px; font-size: 1.0625rem; }
.newsletter-form { display: flex; gap: 12px; max-width: 480px; margin: 0 auto; }
.newsletter-form input {
  flex: 1; padding: 14px 20px; border: 1px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.08); color: var(--white); border-radius: 2px;
  font-size: 0.9375rem;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
.newsletter-form input:focus { outline: none; border-color: var(--accent-gold); }

/* --- Latest Insights --- */
.latest-insights { padding: var(--section-pad) 0; background: var(--off-white); }
.latest-insights h2 { margin-bottom: 40px; }
.insights-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }

/* --- Commitment Pillars --- */
.commitment { padding: var(--section-pad) 0; background: var(--white); }
.commitment h2 { margin-bottom: 40px; }
.pillars-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.pillar-card { padding: 32px 24px; border: 1px solid var(--light-gray); border-radius: 4px; transition: var(--transition); }
.pillar-card:hover { border-color: var(--primary); box-shadow: 0 4px 20px rgba(0,63,45,0.08); }
.pillar-card h4 { margin-bottom: 12px; color: var(--primary); }
.pillar-card p { font-size: 0.875rem; color: var(--text-body); line-height: 1.6; margin-bottom: 16px; }
.pillar-link { font-size: 0.8125rem; font-weight: 600; color: var(--primary); display: inline-flex; align-items: center; gap: 4px; }
.pillar-link:hover { gap: 8px; }

/* --- Service Categories Grid --- */
.service-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; margin-top: 48px; }
.service-card {
  padding: 36px 28px; border: 1px solid var(--light-gray); border-radius: 4px;
  transition: var(--transition); position: relative; overflow: hidden;
}
.service-card::before {
  content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 3px;
  background: var(--primary); transform: scaleX(0); transform-origin: left;
  transition: transform var(--transition);
}
.service-card:hover::before { transform: scaleX(1); }
.service-card:hover { box-shadow: 0 8px 30px rgba(0,63,45,0.08); }
.service-card-icon {
  width: 48px; height: 48px; background: rgba(0,63,45,0.08); border-radius: 8px;
  display: flex; align-items: center; justify-content: center; margin-bottom: 20px;
  color: var(--primary); font-size: 1.25rem;
}
.service-card h3 { margin-bottom: 12px; }
.service-card p { font-size: 0.9rem; color: var(--text-body); line-height: 1.7; margin-bottom: 20px; }
.service-link { font-size: 0.8125rem; font-weight: 600; color: var(--primary); display: inline-flex; align-items: center; gap: 6px; }
.service-link:hover { gap: 10px; }

/* --- Capabilities Grid --- */
.capabilities { padding: var(--section-pad) 0; background: var(--white); }
.capabilities h2 { margin-bottom: 40px; }
.cap-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.cap-card {
  padding: 28px 24px; background: var(--off-white); border-radius: 4px;
  border-left: 3px solid var(--primary); transition: var(--transition);
}
.cap-card:hover { background: var(--white); box-shadow: 0 4px 20px rgba(0,0,0,0.06); }
.cap-card h4 { margin-bottom: 10px; color: var(--primary); }
.cap-card p { font-size: 0.875rem; color: var(--text-body); line-height: 1.6; margin-bottom: 0; }

/* --- Featured Topics Sidebar --- */
.featured-topics { padding: var(--section-pad) 0; background: var(--off-white); }
.topics-list { display: flex; gap: 16px; flex-wrap: wrap; margin-top: 24px; }
.topic-tag {
  padding: 12px 24px; border: 1.5px solid var(--primary); border-radius: 30px;
  font-size: 0.875rem; font-weight: 500; color: var(--primary);
  transition: var(--transition);
}
.topic-tag:hover { background: var(--primary); color: var(--white); }

/* --- Carousel --- */
.carousel-section { padding: var(--section-pad) 0; background: var(--off-white); }
.carousel-track { display: flex; gap: 24px; overflow-x: hidden; scroll-behavior: smooth; }
.carousel-slide {
  min-width: calc(50% - 12px); padding: 36px; background: var(--white);
  border: 1px solid var(--light-gray); border-radius: 4px; flex-shrink: 0;
}
.carousel-slide h4 { margin-bottom: 12px; }
.carousel-slide p { font-size: 0.9rem; color: var(--text-body); line-height: 1.7; }
.carousel-controls { display: flex; gap: 12px; margin-top: 24px; }
.carousel-btn {
  width: 44px; height: 44px; border: 1.5px solid var(--primary); border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--primary); font-size: 1.125rem; transition: var(--transition);
}
.carousel-btn:hover { background: var(--primary); color: var(--white); }

/* --- Testimonial --- */
.testimonial { padding: var(--section-pad) 0; background: var(--primary); text-align: center; }
.testimonial blockquote { font-family: var(--font-heading); font-size: 1.5rem; color: var(--white); line-height: 1.6; max-width: 700px; margin: 0 auto 20px; font-style: italic; }
.testimonial cite { color: rgba(255,255,255,0.7); font-size: 0.9375rem; font-style: normal; }

/* --- Partnership Highlight --- */
.partnership { padding: var(--section-pad) 0; background: var(--off-white); }
.partnership-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
.partnership-visual {
  height: 360px; background: linear-gradient(135deg, var(--navy) 0%, var(--primary) 100%);
  border-radius: 4px; display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,0.3); font-size: 3rem;
}
.partnership-text h2 { margin-bottom: 20px; }
.partnership-text p { font-size: 1.0625rem; line-height: 1.8; }
.stat-row { display: flex; gap: 40px; margin-top: 28px; }
.stat-item strong { display: block; font-size: 2rem; color: var(--primary); font-family: var(--font-heading); }
.stat-item span { font-size: 0.8125rem; color: var(--text-light); }

/* --- Deal Flow CTA --- */
.deal-cta { padding: 60px 0; background: linear-gradient(135deg, var(--navy) 0%, var(--secondary) 100%); text-align: center; }
.deal-cta h2 { color: var(--white); margin-bottom: 16px; }
.deal-cta p { color: rgba(255,255,255,0.7); margin-bottom: 28px; }

/* --- Property Types --- */
.property-types { padding: var(--section-pad) 0; background: var(--white); }
.property-types h2 { margin-bottom: 32px; }
.property-tags { display: flex; gap: 12px; flex-wrap: wrap; }
.property-tag {
  padding: 14px 28px; border: 1.5px solid var(--light-gray); border-radius: 2px;
  font-size: 0.9rem; font-weight: 500; color: var(--text-dark);
  transition: var(--transition);
}
.property-tag:hover { border-color: var(--primary); color: var(--primary); }

/* --- Related Services --- */
.related-services { padding: var(--section-pad) 0; background: var(--off-white); }
.related-services h2 { margin-bottom: 32px; }
.related-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.related-card {
  display: flex; align-items: center; gap: 20px; padding: 24px;
  background: var(--white); border: 1px solid var(--light-gray); border-radius: 4px;
  transition: var(--transition);
}
.related-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.06); }
.related-card h4 { margin-bottom: 4px; }
.related-card p { font-size: 0.8125rem; color: var(--text-light); margin: 0; }

/* --- Related Insights --- */
.related-insights { padding: var(--section-pad) 0; background: var(--white); }
.related-insights h2 { margin-bottom: 32px; }

/* --- Intro Statement (subpage) --- */
.intro-statement { padding: var(--section-pad) 0; background: var(--white); }
.intro-statement .container { max-width: 800px; }
.intro-statement h2 { margin-bottom: 20px; }
.intro-statement p { font-size: 1.125rem; line-height: 1.8; }

/* --- What We Do on subpages --- */
.what-we-do-sub { padding: var(--section-pad) 0; background: var(--off-white); }
.what-we-do-sub h2 { margin-bottom: 32px; }
.wwd-items { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.wwd-item { padding: 28px; background: var(--white); border-radius: 4px; border: 1px solid var(--light-gray); }
.wwd-item h4 { color: var(--primary); margin-bottom: 8px; }
.wwd-item p { font-size: 0.9rem; color: var(--text-body); margin: 0; }

/* --- Footer --- */
.site-footer { background: var(--navy); padding: 60px 0 0; color: rgba(255,255,255,0.7); }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 48px; }
.footer-brand .logo { margin-bottom: 16px; color: var(--white); }
.footer-brand p { font-size: 0.875rem; line-height: 1.7; max-width: 280px; }
.footer-col h4 { font-family: var(--font-body); font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: rgba(255,255,255,0.5); margin-bottom: 16px; }
.footer-col ul li { margin-bottom: 10px; }
.footer-col ul li a { font-size: 0.875rem; transition: color var(--transition); }
.footer-col ul li a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1); padding: 24px 0;
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 0.8rem; margin: 0; }
.footer-legal { display: flex; gap: 24px; }
.footer-legal a { font-size: 0.8rem; transition: color var(--transition); }
.footer-legal a:hover { color: var(--white); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .pillars-grid { grid-template-columns: repeat(2, 1fr); }
  .service-grid { grid-template-columns: repeat(2, 1fr); }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .partnership-inner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  :root { --section-pad: 56px; }
  .main-nav { display: none; }
  .mobile-toggle { display: flex; }
  .hero { min-height: 400px; }
  .hero-sm { min-height: 280px; }
  .insights-grid,
  .insights-list { grid-template-columns: 1fr; }
  .pillars-grid { grid-template-columns: 1fr; }
  .service-grid { grid-template-columns: 1fr; }
  .cap-grid { grid-template-columns: 1fr; }
  .tabs-wrapper { flex-direction: column; }
  .tabs-nav { flex-direction: row; min-width: auto; border-right: none; border-bottom: 1px solid var(--light-gray); overflow-x: auto; }
  .tab-btn { white-space: nowrap; padding: 14px 20px; border-bottom: none; border-right: 1px solid var(--light-gray); }
  .tab-btn:last-child { border-right: none; }
  .tab-btn.active::before { top: auto; bottom: 0; left: 0; right: 0; width: auto; height: 3px; }
  .tab-panel { padding: 28px 20px; }
  .newsletter-form { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-legal { flex-wrap: wrap; justify-content: center; }
  .related-grid { grid-template-columns: 1fr; }
  .wwd-items { grid-template-columns: 1fr; }
  .stat-row { flex-direction: column; gap: 20px; }
  .carousel-slide { min-width: 100%; }
  .announcement-banner .container { flex-direction: column; gap: 12px; }
}

@media (max-width: 480px) {
  :root { --section-pad: 40px; }
  .header-inner { height: 60px; }
  .hero { margin-top: 60px; }
  .mobile-nav { top: 60px; height: calc(100vh - 60px); }
}

/* ===== GlobalStone — Corporate Real Estate CSS ===== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #003F2D;
  --secondary: #012A2D;
  --navy: #0A1628;
  --accent-gold: #C5A46D;
  --accent-teal: #1A8A7D;
  --light-gray: #E6E6E6;
  --mid-gray: #8A8F98;
  --off-white: #F5F5F5;
  --white: #FFFFFF;
  --text-dark: #1A1A2E;
  --text-body: #3A3A4A;
  --text-light: #6B6B7B;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'Georgia', 'Times New Roman', serif;
  --max-width: 1280px;
  --section-pad: 80px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font-body); color: var(--text-body); line-height: 1.6; background: var(--white); -webkit-font-smoothing: antialiased; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* --- Typography --- */
h1, h2, h3, h4 { font-family: var(--font-heading); color: var(--text-dark); line-height: 1.2; font-weight: 700; }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.625rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }
p { margin-bottom: 1rem; }
.section-label { font-family: var(--font-body); font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 2px; color: var(--accent-teal); margin-bottom: 12px; }

/* --- Buttons --- */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 0.875rem; font-weight: 600; padding: 14px 28px;
  border-radius: 2px; transition: var(--transition); letter-spacing: 0.5px;
}
.btn-primary { background: var(--primary); color: var(--white); }
.btn-primary:hover { background: var(--secondary); }
.btn-outline { border: 1.5px solid var(--primary); color: var(--primary); background: transparent; }
.btn-outline:hover { background: var(--primary); color: var(--white); }
.btn-gold { background: var(--accent-gold); color: var(--navy); }
.btn-gold:hover { background: #b8944f; }
.btn-white { background: var(--white); color: var(--primary); }
.btn-white:hover { background: var(--light-gray); }
.btn-arrow::after { content: '→'; transition: transform var(--transition); }
.btn-arrow:hover::after { transform: translateX(4px); }

/* --- Header / Navigation --- */
.site-header {
  position: fixed; top: 0; left: 0; width: 100%; z-index: 1000;
  background: var(--white); border-bottom: 1px solid rgba(0,0,0,0.08);
  transition: box-shadow var(--transition);
}
.site-header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; height: 72px;
}
.logo { font-family: var(--font-heading); font-size: 1.5rem; font-weight: 700; color: var(--primary); }
.logo span { color: var(--accent-gold); }

/* Desktop Nav */
.main-nav { display: flex; align-items: center; gap: 0; }
.main-nav > li { position: relative; }
.main-nav > li > a,
.main-nav > li > button {
  display: flex; align-items: center; gap: 4px;
  padding: 24px 16px; font-size: 0.875rem; font-weight: 500;
  color: var(--text-dark); transition: color var(--transition);
}
.main-nav > li > a:hover,
.main-nav > li > button:hover { color: var(--primary); }
.nav-chevron { font-size: 0.625rem; transition: transform var(--transition); }
.nav-item-active .nav-chevron { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  position: absolute; top: 100%; left: 50%; transform: translateX(-50%);
  width: 620px; background: var(--white); border: 1px solid rgba(0,0,0,0.08);
  box-shadow: 0 20px 60px rgba(0,0,0,0.12); border-radius: 0 0 4px 4px;
  opacity: 0; visibility: hidden; pointer-events: none;
  transition: opacity 0.25s ease, visibility 0.25s ease;
  padding: 32px; display: grid; grid-template-columns: 1fr 1fr; gap: 32px;
}
.mega-menu.active { opacity: 1; visibility: visible; pointer-events: auto; }
.mega-menu-col h4 { font-family: var(--font-body); font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--mid-gray); margin-bottom: 16px; }
.mega-menu-col ul li a {
  display: block; padding: 8px 0; font-size: 0.9rem; color: var(--text-dark);
  transition: color var(--transition); border-bottom: 1px solid transparent;
}
.mega-menu-col ul li a:hover { color: var(--primary); }

/* Mobile Nav */
.mobile-toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.mobile-toggle span { display: block; width: 24px; height: 2px; background: var(--text-dark); transition: var(--transition); }
.mobile-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px,5px); }
.mobile-toggle.active span:nth-child(2) { opacity: 0; }
.mobile-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px,-5px); }

.mobile-nav {
  display: none; position: fixed; top: 72px; left: 0; width: 100%; height: calc(100vh - 72px);
  background: var(--white); overflow-y: auto; padding: 24px;
}
.mobile-nav.active { display: block; }
.mobile-nav > li { border-bottom: 1px solid var(--light-gray); }
.mobile-nav > li > a,
.mobile-nav > li > button {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; padding: 16px 0; font-size: 1rem; font-weight: 500; color: var(--text-dark);
}
.mobile-accordion { display: none; padding: 0 0 16px 16px; }
.mobile-accordion.active { display: block; }
.mobile-accordion li { margin-bottom: 4px; }
.mobile-accordion li a { display: block; padding: 8px 0; font-size: 0.9rem; color: var(--text-body); }
.mobile-accordion h5 { font-family: var(--font-body); font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--mid-gray); margin: 8px 0; }

/* --- Hero Sections --- */
.hero {
  position: relative; min-height: 520px; display: flex; align-items: center;
  background-color: var(--navy); overflow: hidden; margin-top: 72px;
}
.hero-bg {
  position: absolute; inset: 0; background-size: cover; background-position: center;
  opacity: 0.35;
}
.hero-overlay { position: absolute; inset: 0; background: linear-gradient(135deg, rgba(10,22,40,0.85) 0%, rgba(0,63,45,0.6) 100%); }
.hero-content { position: relative; z-index: 2; max-width: 640px; padding: 80px 0; }
.hero-content h1 { color: var(--white); margin-bottom: 20px; }
.hero-content p { color: rgba(255,255,255,0.85); font-size: 1.125rem; margin-bottom: 32px; line-height: 1.7; }

.hero-sm { min-height: 360px; }
.hero-sm .hero-content { padding: 60px 0; }

/* --- Featured Insights (3-card row) --- */
.featured-insights { padding: var(--section-pad) 0; background: var(--white); }
.insights-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.insight-card {
  border: 1px solid var(--light-gray); border-radius: 4px; overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
}
.insight-card:hover { box-shadow: 0 8px 30px rgba(0,0,0,0.08); transform: translateY(-4px); }
.insight-card-img {
  height: 200px; background-color: var(--navy); background-size: cover;
  background-position: center; position: relative;
}
.insight-card-img::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(to bottom, transparent 60%, rgba(10,22,40,0.3));
}
.insight-card-body { padding: 24px; }
.insight-card-tag { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--accent-teal); margin-bottom: 10px; }
.insight-card-body h3 { margin-bottom: 8px; font-size: 1.125rem; }
.insight-card-body p { font-size: 0.875rem; color: var(--text-light); margin-bottom: 0; }
.insight-card-date { font-size: 0.8rem; color: var(--mid-gray); margin-top: 12px; }

/* --- Announcement Banner --- */
.announcement-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  padding: 28px 0; text-align: center;
}
.announcement-banner .container { display: flex; align-items: center; justify-content: center; gap: 24px; flex-wrap: wrap; }
.announcement-banner p { color: var(--white); font-size: 1.0625rem; font-weight: 500; margin: 0; }

/* --- About Statement --- */
.about-statement { padding: var(--section-pad) 0; background: var(--off-white); }
.about-inner { max-width: 800px; }
.about-inner h2 { margin-bottom: 24px; }
.about-inner p { font-size: 1.125rem; color: var(--text-body); line-height: 1.8; margin-bottom: 28px; }

/* --- What We Do (Vertical Tabs) --- */
.what-we-do { padding: var(--section-pad) 0; background: var(--white); }
.tabs-wrapper { display: flex; gap: 0; margin-top: 40px; border: 1px solid var(--light-gray); border-radius: 4px; overflow: hidden; min-height: 320px; }
.tabs-nav { display: flex; flex-direction: column; min-width: 240px; background: var(--off-white); border-right: 1px solid var(--light-gray); }
.tab-btn {
  padding: 20px 24px; text-align: left; font-size: 0.9375rem; font-weight: 500;
  color: var(--text-body); border-bottom: 1px solid var(--light-gray);
  transition: var(--transition); position: relative;
}
.tab-btn:last-child { border-bottom: none; }
.tab-btn:hover { background: rgba(0,63,45,0.05); }
.tab-btn.active {
  background: var(--white); color: var(--primary); font-weight: 600;
}
.tab-btn.active::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--primary); }
.tab-panel { display: none; padding: 40px; flex: 1; }
.tab-panel.active { display: flex; flex-direction: column; justify-content: center; }
.tab-panel h3 { margin-bottom: 16px; color: var(--primary); }
.tab-panel p { font-size: 1.0625rem; line-height: 1.8; margin-bottom: 24px; color: var(--text-body); }
.tab-services-list { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 24px; }
.tab-services-list li { font-size: 0.875rem; padding: 6px 14px; background: var(--off-white); border-radius: 20px; color: var(--text-dark); }

/* --- Newsletter --- */
.newsletter { padding: var(--section-pad) 0; background: var(--navy); text-align: center; }
.newsletter h2 { color: var(--white); margin-bottom: 12px; }
.newsletter p { color: rgba(255,255,255,0.7); margin-bottom: 32px; font-size: 1.0625rem; }
.newsletter-form { display: flex; gap: 12px; max-width: 480px; margin: 0 auto; }
.newsletter-form input {
  flex: 1; padding: 14px 20px; border: 1px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.08); color: var(--white); border-radius: 2px;
  font-size: 0.9375rem;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
.newsletter-form input:focus { outline: none; border-color: var(--accent-gold); }

/* --- Latest Insights --- */
.latest-insights { padding: var(--section-pad) 0; background: var(--off-white); }
.latest-insights h2 { margin-bottom: 40px; }
.insights-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }

/* --- Commitment Pillars --- */
.commitment { padding: var(--section-pad) 0; background: var(--white); }
.commitment h2 { margin-bottom: 40px; }
.pillars-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.pillar-card { padding: 32px 24px; border: 1px solid var(--light-gray); border-radius: 4px; transition: var(--transition); }
.pillar-card:hover { border-color: var(--primary); box-shadow: 0 4px 20px rgba(0,63,45,0.08); }
.pillar-card h4 { margin-bottom: 12px; color: var(--primary); }
.pillar-card p { font-size: 0.875rem; color: var(--text-body); line-height: 1.6; margin-bottom: 16px; }
.pillar-link { font-size: 0.8125rem; font-weight: 600; color: var(--primary); display: inline-flex; align-items: center; gap: 4px; }
.pillar-link:hover { gap: 8px; }

/* --- Service Categories Grid --- */
.service-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; margin-top: 48px; }
.service-card {
  padding: 36px 28px; border: 1px solid var(--light-gray); border-radius: 4px;
  transition: var(--transition); position: relative; overflow: hidden;
}
.service-card::before {
  content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 3px;
  background: var(--primary); transform: scaleX(0); transform-origin: left;
  transition: transform var(--transition);
}
.service-card:hover::before { transform: scaleX(1); }
.service-card:hover { box-shadow: 0 8px 30px rgba(0,63,45,0.08); }
.service-card-icon {
  width: 48px; height: 48px; background: rgba(0,63,45,0.08); border-radius: 8px;
  display: flex; align-items: center; justify-content: center; margin-bottom: 20px;
  color: var(--primary); font-size: 1.25rem;
}
.service-card h3 { margin-bottom: 12px; }
.service-card p { font-size: 0.9rem; color: var(--text-body); line-height: 1.7; margin-bottom: 20px; }
.service-link { font-size: 0.8125rem; font-weight: 600; color: var(--primary); display: inline-flex; align-items: center; gap: 6px; }
.service-link:hover { gap: 10px; }

/* --- Capabilities Grid --- */
.capabilities { padding: var(--section-pad) 0; background: var(--white); }
.capabilities h2 { margin-bottom: 40px; }
.cap-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.cap-card {
  padding: 28px 24px; background: var(--off-white); border-radius: 4px;
  border-left: 3px solid var(--primary); transition: var(--transition);
}
.cap-card:hover { background: var(--white); box-shadow: 0 4px 20px rgba(0,0,0,0.06); }
.cap-card h4 { margin-bottom: 10px; color: var(--primary); }
.cap-card p { font-size: 0.875rem; color: var(--text-body); line-height: 1.6; margin-bottom: 0; }

/* --- Featured Topics Sidebar --- */
.featured-topics { padding: var(--section-pad) 0; background: var(--off-white); }
.topics-list { display: flex; gap: 16px; flex-wrap: wrap; margin-top: 24px; }
.topic-tag {
  padding: 12px 24px; border: 1.5px solid var(--primary); border-radius: 30px;
  font-size: 0.875rem; font-weight: 500; color: var(--primary);
  transition: var(--transition);
}
.topic-tag:hover { background: var(--primary); color: var(--white); }

/* --- Carousel --- */
.carousel-section { padding: var(--section-pad) 0; background: var(--off-white); }
.carousel-track { display: flex; gap: 24px; overflow-x: hidden; scroll-behavior: smooth; }
.carousel-slide {
  min-width: calc(50% - 12px); padding: 36px; background: var(--white);
  border: 1px solid var(--light-gray); border-radius: 4px; flex-shrink: 0;
}
.carousel-slide h4 { margin-bottom: 12px; }
.carousel-slide p { font-size: 0.9rem; color: var(--text-body); line-height: 1.7; }
.carousel-controls { display: flex; gap: 12px; margin-top: 24px; }
.carousel-btn {
  width: 44px; height: 44px; border: 1.5px solid var(--primary); border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--primary); font-size: 1.125rem; transition: var(--transition);
}
.carousel-btn:hover { background: var(--primary); color: var(--white); }

/* --- Testimonial --- */
.testimonial { padding: var(--section-pad) 0; background: var(--primary); text-align: center; }
.testimonial blockquote { font-family: var(--font-heading); font-size: 1.5rem; color: var(--white); line-height: 1.6; max-width: 700px; margin: 0 auto 20px; font-style: italic; }
.testimonial cite { color: rgba(255,255,255,0.7); font-size: 0.9375rem; font-style: normal; }

/* --- Partnership Highlight --- */
.partnership { padding: var(--section-pad) 0; background: var(--off-white); }
.partnership-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
.partnership-visual {
  height: 360px; background: linear-gradient(135deg, var(--navy) 0%, var(--primary) 100%);
  border-radius: 4px; display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,0.3); font-size: 3rem;
}
.partnership-text h2 { margin-bottom: 20px; }
.partnership-text p { font-size: 1.0625rem; line-height: 1.8; }
.stat-row { display: flex; gap: 40px; margin-top: 28px; }
.stat-item strong { display: block; font-size: 2rem; color: var(--primary); font-family: var(--font-heading); }
.stat-item span { font-size: 0.8125rem; color: var(--text-light); }

/* --- Deal Flow CTA --- */
.deal-cta { padding: 60px 0; background: linear-gradient(135deg, var(--navy) 0%, var(--secondary) 100%); text-align: center; }
.deal-cta h2 { color: var(--white); margin-bottom: 16px; }
.deal-cta p { color: rgba(255,255,255,0.7); margin-bottom: 28px; }

/* --- Property Types --- */
.property-types { padding: var(--section-pad) 0; background: var(--white); }
.property-types h2 { margin-bottom: 32px; }
.property-tags { display: flex; gap: 12px; flex-wrap: wrap; }
.property-tag {
  padding: 14px 28px; border: 1.5px solid var(--light-gray); border-radius: 2px;
  font-size: 0.9rem; font-weight: 500; color: var(--text-dark);
  transition: var(--transition);
}
.property-tag:hover { border-color: var(--primary); color: var(--primary); }

/* --- Related Services --- */
.related-services { padding: var(--section-pad) 0; background: var(--off-white); }
.related-services h2 { margin-bottom: 32px; }
.related-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.related-card {
  display: flex; align-items: center; gap: 20px; padding: 24px;
  background: var(--white); border: 1px solid var(--light-gray); border-radius: 4px;
  transition: var(--transition);
}
.related-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.06); }
.related-card h4 { margin-bottom: 4px; }
.related-card p { font-size: 0.8125rem; color: var(--text-light); margin: 0; }

/* --- Related Insights --- */
.related-insights { padding: var(--section-pad) 0; background: var(--white); }
.related-insights h2 { margin-bottom: 32px; }

/* --- Intro Statement (subpage) --- */
.intro-statement { padding: var(--section-pad) 0; background: var(--white); }
.intro-statement .container { max-width: 800px; }
.intro-statement h2 { margin-bottom: 20px; }
.intro-statement p { font-size: 1.125rem; line-height: 1.8; }

/* --- What We Do on subpages --- */
.what-we-do-sub { padding: var(--section-pad) 0; background: var(--off-white); }
.what-we-do-sub h2 { margin-bottom: 32px; }
.wwd-items { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.wwd-item { padding: 28px; background: var(--white); border-radius: 4px; border: 1px solid var(--light-gray); }
.wwd-item h4 { color: var(--primary); margin-bottom: 8px; }
.wwd-item p { font-size: 0.9rem; color: var(--text-body); margin: 0; }

/* --- Footer --- */
.site-footer { background: var(--navy); padding: 60px 0 0; color: rgba(255,255,255,0.7); }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 48px; }
.footer-brand .logo { margin-bottom: 16px; color: var(--white); }
.footer-brand p { font-size: 0.875rem; line-height: 1.7; max-width: 280px; }
.footer-col h4 { font-family: var(--font-body); font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: rgba(255,255,255,0.5); margin-bottom: 16px; }
.footer-col ul li { margin-bottom: 10px; }
.footer-col ul li a { font-size: 0.875rem; transition: color var(--transition); }
.footer-col ul li a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1); padding: 24px 0;
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 0.8rem; margin: 0; }
.footer-legal { display: flex; gap: 24px; }
.footer-legal a { font-size: 0.8rem; transition: color var(--transition); }
.footer-legal a:hover { color: var(--white); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .pillars-grid { grid-template-columns: repeat(2, 1fr); }
  .service-grid { grid-template-columns: repeat(2, 1fr); }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .partnership-inner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  :root { --section-pad: 56px; }
  .main-nav { display: none; }
  .mobile-toggle { display: flex; }
  .hero { min-height: 400px; }
  .hero-sm { min-height: 280px; }
  .insights-grid,
  .insights-list { grid-template-columns: 1fr; }
  .pillars-grid { grid-template-columns: 1fr; }
  .service-grid { grid-template-columns: 1fr; }
  .cap-grid { grid-template-columns: 1fr; }
  .tabs-wrapper { flex-direction: column; }
  .tabs-nav { flex-direction: row; min-width: auto; border-right: none; border-bottom: 1px solid var(--light-gray); overflow-x: auto; }
  .tab-btn { white-space: nowrap; padding: 14px 20px; border-bottom: none; border-right: 1px solid var(--light-gray); }
  .tab-btn:last-child { border-right: none; }
  .tab-btn.active::before { top: auto; bottom: 0; left: 0; right: 0; width: auto; height: 3px; }
  .tab-panel { padding: 28px 20px; }
  .newsletter-form { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-legal { flex-wrap: wrap; justify-content: center; }
  .related-grid { grid-template-columns: 1fr; }
  .wwd-items { grid-template-columns: 1fr; }
  .stat-row { flex-direction: column; gap: 20px; }
  .carousel-slide { min-width: 100%; }
  .announcement-banner .container { flex-direction: column; gap: 12px; }
}

@media (max-width: 480px) {
  :root { --section-pad: 40px; }
  .header-inner { height: 60px; }
  .hero { margin-top: 60px; }
  .mobile-nav { top: 60px; height: calc(100vh - 60px); }
}

